  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Sertraline, a close bicyclic amine analogue with a dichlorophenyl group, is concentrated 20-50-fold in brain over blood in animal pharmacokinetic studies, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A sertraline primary carboxamide analogue achieves a CSF:free plasma ratio of 1:1 in rat CNS penetration studies, indicating excellent brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Mianserin, an N-methyl tetracyclic amine, shows a rat logBB of 0.99, consistent with good brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine, an N-methyl aporphine alkaloid, reaches brain tissue concentrations nearly equal to plasma in rats, showing effective BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Chlorcyclizine, a lipophilic N-methyl piperazine with a chlorophenyl group, crosses the BBB in mice with brain levels comparable to liver.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Isocorydine, an N-methyl aporphine, effectively crosses the BBB in rats with considerable brain levels detected within 10 minutes of administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The dichlorophenol-containing PET ligand NCQ 258 passes rapidly across the BBB in Cynomolgus monkeys.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "7-hydroxy-Δ1-THC rapidly penetrates the CNS in mice with no effective blood-brain barrier, supporting CNS access for phenolic lipophilic analogues.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS penetration via direct brain, CSF, or PET measurements. The query's lipophilic, basic amine scaffold with aromatic chlorines and a phenol aligns with these brain-penetrant molecules, so the prediction is pass.",
